def analyze_ciphertexts():
    # C1 and C2 data from server
    c1 = [206, 220, 76, 109, 97, 54, 177, 150, 19, 0, 232, 112, 128, 175, 140, 36, 85, 217, 49, 9, 159, 14, 119, 24, 148, 96, 179, 21, 204, 5, 189, 251, 77, 26, 75, 210, 198, 157, 131, 86]
    c2 = [206, 209, 70, 111, 97, 40, 177, 151, 19, 0, 232, 112, 151, 212, 253, 50, 94, 230]

    print("Analysis of C1 and C2 ciphertexts:")
    print("\n1. Length comparison:")
    print(f"C1 length: {len(c1)} bytes")
    print(f"C2 length: {len(c2)} bytes")
    print(f"Length difference: {len(c1) - len(c2)} bytes")

    print("\n2. Matching patterns in first bytes:")
    matching_prefix_length = 0
    for i in range(min(len(c1), len(c2))):
        if c1[i] == c2[i]:
            matching_prefix_length += 1
            print(f"Match at position {i}: {c1[i]}")
        else:
            break

    print("\n3. Analysis of identical first byte [206]:")
    print("First byte 206 (0xce) is identical in both ciphertexts")

    print("\n4. Common subsequences:")
    min_len = min(len(c1), len(c2))
    matching_positions = []
    matching_sequences = []
    current_sequence = []

    for i in range(min_len):
        if c1[i] == c2[i]:
            current_sequence.append((i, c1[i]))
            matching_positions.append(i)
        else:
            if current_sequence:
                matching_sequences.append(current_sequence[:])
                current_sequence = []

    if current_sequence:
        matching_sequences.append(current_sequence)

    print("Matching positions:", matching_positions)
    print("\nMatching sequences:")
    for seq in matching_sequences:
        if len(seq) > 1:
            print(f"Sequence at positions {[p[0] for p in seq]}: {[p[1] for p in seq]}")

    print("\n5. XOR analysis of overlapping bytes:")
    for i in range(min_len):
        xor_result = c1[i] ^ c2[i]
        print(f"Position {i}: {c1[i]} ^ {c2[i]} = {xor_result} (0x{xor_result:02x})")

    print("\n6. Pattern analysis:")
    # Look for repeating 2-byte patterns in C1
    print("Repeating 2-byte patterns in C1:")
    for i in range(len(c1)-1):
        pattern = (c1[i], c1[i+1])
        for j in range(i+2, len(c1)-1):
            if (c1[j], c1[j+1]) == pattern:
                print(f"Pattern {pattern} repeats at positions {i} and {j}")

    # Look for repeating 2-byte patterns in C2
    print("\nRepeating 2-byte patterns in C2:")
    for i in range(len(c2)-1):
        pattern = (c2[i], c2[i+1])
        for j in range(i+2, len(c2)-1):
            if (c2[j], c2[j+1]) == pattern:
                print(f"Pattern {pattern} repeats at positions {i} and {j}")

if __name__ == "__main__":
    analyze_ciphertexts()

